const ext = ($('Extract Order Data').first().json.output) || {};
const clean = (rows) => rows.map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const customers = clean($('Read Customers').all());
const products = clean($('Read Products').all());
const orders = clean($('Read Orders').all());

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const lc = (v) => norm(v).toLowerCase();

const customerName = norm(ext.customer_name);
const customerId = norm(ext.customer_id);
const poNumber = norm(ext.po_number);
const sku = norm(ext.sku);
const qtyRaw = norm(ext.quantity);
const unitPrice = norm(ext.unit_price);
const deliveryAddress = norm(ext.delivery_address);
const deliveryDate = norm(ext.requested_delivery_date);

const reasons = [];

// 9. Guard: document produced no usable text / extraction empty
const anyValue = [customerName, customerId, poNumber, sku, qtyRaw, deliveryAddress, deliveryDate].some(v => v !== "");
if (!anyValue) reasons.push("Document could not be read or no data was extracted");

// 1-strict. Required fields present and clear
const required = { customer_name: customerName, customer_id: customerId, po_number: poNumber, sku: sku, quantity: qtyRaw, delivery_address: deliveryAddress, requested_delivery_date: deliveryDate };
for (const k of Object.keys(required)) { if (!required[k]) reasons.push("Missing or unclear field: " + k); }

// 4. Quantity must be a valid positive whole number
const qty = Number(qtyRaw.replace(/[^0-9.\-]/g, ""));
if (qtyRaw && (!Number.isFinite(qty) || qty <= 0 || !Number.isInteger(qty))) reasons.push("Quantity is not a valid positive whole number: " + qtyRaw);

// 1. Customer exists   // 7. customer/order consistency
const custMatch = customers.find(c => lc(c.customer_id) === lc(customerId));
if (customerId && !custMatch) reasons.push("Unknown customer ID: " + customerId);
if (custMatch && customerName && lc(custMatch.customer_name) !== lc(customerName)) reasons.push("Customer name does not match customer ID on record");

// 8. Duplicate PO detection
const dup = orders.find(o => lc(o.po_number) === lc(poNumber));
if (poNumber && dup) reasons.push("Duplicate PO number: " + poNumber);

// 3,5,6. SKU exists, is active, inventory available
const prodMatch = products.find(p => lc(p.sku) === lc(sku));
if (sku && !prodMatch) reasons.push("Unknown SKU: " + sku);
if (prodMatch) {
  const active = lc(prodMatch.active);
  if (!["true", "yes", "active", "1"].includes(active)) reasons.push("SKU is not active: " + sku);
  const stock = Number(norm(prodMatch.stock !== undefined ? prodMatch.stock : prodMatch.inventory).replace(/[^0-9.\-]/g, ""));
  if (Number.isFinite(qty) && qty > 0 && Number.isFinite(stock) && stock < qty) reasons.push("Insufficient inventory for " + sku + ": need " + qty + ", have " + stock);
}

const status = reasons.length === 0 ? "PASS" : "FAIL";
let sourceFrom = ""; let sourceSubject = "";
try { sourceFrom = norm($("Gmail Trigger").first().json.from); sourceSubject = norm($("Gmail Trigger").first().json.subject); } catch (e) {}

return [{ json: {
  validation_status: status,
  order_status: status === "PASS" ? "created" : "blocked",
  review_status: status === "PASS" ? "not_required" : "pending",
  reason_text: reasons.join("; "),
  reasons: reasons,
  customer_name: customerName,
  customer_id: customerId,
  po_number: poNumber,
  sku: sku,
  quantity: Number.isFinite(qty) ? qty : qtyRaw,
  unit_price: unitPrice,
  delivery_address: deliveryAddress,
  requested_delivery_date: deliveryDate,
  customer_email: (custMatch && custMatch.email) ? custMatch.email : sourceFrom,
  source_email_from: sourceFrom,
  source_subject: sourceSubject,
  timestamp: new Date().toISOString(),
} }];

return [
  { json: { customer_id: 'CUST-001', customer_name: 'Acme Retail Ltd', email: 'buyer@acme-retail.co.uk', active: 'TRUE' } },
  { json: { customer_id: 'CUST-002', customer_name: 'Beta Wholesale', email: 'orders@beta.co.uk', active: 'TRUE' } },
];

return [
  { json: { sku: 'SKU-100', name: 'Widget A', active: 'TRUE', stock: '500', unit_price: '4.50' } },
  { json: { sku: 'SKU-200', name: 'Widget B', active: 'FALSE', stock: '0', unit_price: '9.00' } },
];

return [{ json: {
  po_number: '', customer_id: '', customer_name: '', sku: '', quantity: '',
  unit_price: '', delivery_address: '', requested_delivery_date: '', order_status: '', timestamp: '',
} }];

return [{ json: {
  timestamp: '', po_number: '', customer_id: '', customer_name: '', sku: '', quantity: '',
  reason: '', review_status: '', source_email_from: '', source_subject: '',
} }];

return [{ json: {
  timestamp: '', po_number: '', customer_id: '', sku: '', quantity: '',
  validation_status: '', order_status: '', review_status: '', action: '', errors: '',
} }];
